{
  "items": [
    {
      "name": "Finsupp.support_subset_iff",
      "type": " {α : Type u_1} {M : Type u_4} [Zero M] {s : Set α} {f : α →₀ M} : ↑f.support ⊆ s ↔ ∀ a ∉ s, f a = 0",
      "module": "Mathlib.Data.Finsupp.Defs"
    },
    {
      "name": "Polynomial.coe_coeffs_subset_iff",
      "type": " {R : Type u} [Semiring R] {p : Polynomial R} {s : Set R} : ↑p.coeffs ⊆ s ↔ ∀ (n : ℕ), p.coeff n ≠ 0 → p.coeff n ∈ s",
      "module": "Mathlib.Algebra.Polynomial.Basic"
    },
    {
      "name": "Polynomial.coeffs_subset_iff",
      "type": " {R : Type u} [Semiring R] {p : Polynomial R} {s : Finset R} : p.coeffs ⊆ s ↔ ∀ (n : ℕ), p.coeff n ≠ 0 → p.coeff n ∈ s",
      "module": "Mathlib.Algebra.Polynomial.Basic"
    },
    {
      "name": "Finsupp.le_def",
      "type": " {ι : Type u_1} {M : Type u_2} [Zero M] [LE M] {f g : ι →₀ M} : f ≤ g ↔ ∀ (i : ι), f i ≤ g i",
      "module": "Mathlib.Order.Preorder.Finsupp"
    },
    {
      "name": "Finsupp.le_iff",
      "type": " {ι : Type u_1} {α : Type u_3} [AddCommMonoid α] [PartialOrder α] [CanonicallyOrderedAdd α] (f g : ι →₀ α) : f ≤ g ↔ ∀ i ∈ f.support, f i ≤ g i",
      "module": "Mathlib.Data.Finsupp.Order"
    },
    {
      "name": "Finsupp.le_iff'",
      "type": " {ι : Type u_1} {α : Type u_3} [AddCommMonoid α] [PartialOrder α] [CanonicallyOrderedAdd α] (f g : ι →₀ α) {s : Finset ι} (hf : f.support ⊆ s) : f ≤ g ↔ ∀ i ∈ s, f i ≤ g i",
      "module": "Mathlib.Data.Finsupp.Order"
    },
    {
      "name": "MvPolynomial.coeffsIn_le",
      "type": " {R : Type u_2} {S : Type u_3} {σ : Type u_4} [CommSemiring R] [CommSemiring S] [Module R S] {M : Submodule R S} {N : Submodule R (MvPolynomial σ S)} : MvPolynomial.coeffsIn σ M ≤ N ↔ ∀ m ∈ M, ∀ (i : σ →₀ ℕ), (MvPolynomial.monomial i) m ∈ N",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "Polynomial.degree_le_iff_coeff_zero",
      "type": " {R : Type u} [Semiring R] (f : Polynomial R) (n : WithBot ℕ) : f.degree ≤ n ↔ ∀ (m : ℕ), n < ↑m → f.coeff m = 0",
      "module": "Mathlib.Algebra.Polynomial.Degree.Defs"
    }
  ]
}
